static void flush_cb(lv_display_t * disp, const lv_area_t * area, uint8_t * color_p)
{
    lv_nuttx_fb_t * dsc = lv_display_get_driver_data(disp);

    /* DIAG: a Data abort fires inside file_vioctl() on one of the ioctl()
     * calls below, with inode->u.i_ops holding a non-NULL garbage value --
     * i.e. the fd is not a live descriptor.  Log the pointers and the fd for
     * the first few flushes so the bad value reaches the serial log ahead of
     * the fault, then bail out rather than faulting.
     */

    {
        static int diag_count = 0;
        if(diag_count < 5) {
            diag_count++;
            syslog(LOG_ERR, "[fbdiag] flush#%d disp=%p dsc=%p\n",
                   diag_count, (void *)disp, (void *)dsc);
            if(dsc != NULL) {
                syslog(LOG_ERR, "[fbdiag]   fd=%d mem=%p mem2=%p %ux%u\n",
                       dsc->fd, dsc->mem, dsc->mem2,
                       (unsigned)dsc->vinfo.xres, (unsigned)dsc->vinfo.yres);
            }
        }
    }

    if(dsc == NULL) {
        syslog(LOG_ERR, "[fbdiag] dsc is NULL, skip flush\n");
        lv_display_flush_ready(disp);
        return;
    }

    if(dsc->fd < 0) {
        syslog(LOG_ERR, "[fbdiag] bad fd=%d, skip ioctl\n", dsc->fd);
        lv_display_flush_ready(disp);
        return;
    }

    /* Skip the non-last flush */

    if(!lv_display_flush_is_last(disp)) {
        lv_display_flush_ready(disp);
        return;
    }

    if(dsc->mem == NULL ||
       area->x2 < 0 || area->y2 < 0 ||
       area->x1 > (int32_t)dsc->vinfo.xres - 1 || area->y1 > (int32_t)dsc->vinfo.yres - 1) {
        lv_display_flush_ready(disp);
        return;
    }

#if defined(CONFIG_FB_UPDATE)
    /*May be some direct update command is required*/
    int yoffset = disp->buf_act == disp->buf_1 ?
                  0 : dsc->mem2_yoffset;

    /* Join the areas to update */
    lv_area_t dirty_area;
    lv_display_get_dirty_area(disp, &dirty_area);

    struct fb_area_s fb_area;
    fb_area.x = dirty_area.x1;
    fb_area.y = dirty_area.y1 + yoffset;
    fb_area.w = lv_area_get_width(&dirty_area);
    fb_area.h = lv_area_get_height(&dirty_area);
    {
        static int upd_diag = 0;
        if(upd_diag < 3) {
            upd_diag++;
            syslog(LOG_ERR, "[fbdiag] pre FBIO_UPDATE fd=%d %d,%d %dx%d\n",
                   dsc->fd, (int)fb_area.x, (int)fb_area.y,
                   (int)fb_area.w, (int)fb_area.h);
        }
        if(ioctl(dsc->fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&fb_area)) < 0) {
            LV_LOG_ERROR("ioctl(FBIO_UPDATE) failed: %d", errno);
        }
        if(upd_diag <= 3) {
            syslog(LOG_ERR, "[fbdiag] post FBIO_UPDATE ok\n");
        }
    }
#endif

    /* double framebuffer */

    if(dsc->mem2 != NULL) {
        if(disp->buf_act == disp->buf_1) {
            dsc->pinfo.yoffset = 0;
        }
        else {
            dsc->pinfo.yoffset = dsc->mem2_yoffset;
        }

