#!/usr/bin/env python3
"""Stop ai_chat_bridge_agent_running() from stalling the UI thread.

The probe walks all of /proc and does an fopen/fgets/fclose per process to
look for ai_agent's cmdline.  That is dozens of synchronous filesystem round
trips, and all four callers are LVGL event callbacks -- the PTT press, the PTT
release, the AI page's check button and the once-per-second status refresh.
While it runs, lv_timer_handler() cannot return, so the panel stops responding
to touch: the "microphone tap freezes the UI" symptom.

The answer is a short time window cache.  Whether ai_agent is alive is not
something that changes between two taps a few hundred milliseconds apart, so
one scan every few seconds carries the same information at a fraction of the
cost.  A tap that lands inside the window returns the cached answer without
touching the filesystem at all.

The window is deliberately short so that starting or killing the agent from
the shell still shows up in the UI within a few seconds.
"""
import sys

PATH = ("/home/openvela/openvela/contest2026_120_haohaoxuexitiantianxiangshang"
        "/app/hello_app/ai_chat_bridge.c")

OLD_SIG = """bool ai_chat_bridge_agent_running(void)
{
  DIR *dir;
  struct dirent *entry;
  bool found = false;

  dir = opendir("/proc");"""

NEW_SIG = """/* Cached liveness probe.
 *
 * scan_agent_running() below is expensive: it enumerates /proc and reads a
 * cmdline file per process.  Every caller of the public wrapper is an LVGL
 * event callback, so paying that cost inline blocks lv_timer_handler() and
